export const JV_NOTES: Record<string, L4Note> = {
  "l4-jv-first": { recapEn: "Everything in a class, every variable typed, main the single door — errors move to compile time.", recapBn: "সবকিছু class-এ, প্রতিটি variable typed, main একমাত্র দরজা — error compile time-এ সরে যায়।" },
  "l4-jv-operators": { recapEn: "parseInt converts or throws; the exception is the validation, and range is the second layer.", recapBn: "parseInt convert করে বা throw করে; exception-ই validation, আর range দ্বিতীয় স্তর।" },
  "l4-jv-control": { recapEn: "Arrow switch yields values with no fall-through; typed booleans kill the = trap at compile time.", recapBn: "Arrow switch fall-through ছাড়া মান yield করে; typed boolean = ফাঁদ compile time-এই মারে।" },
  "l4-jv-arrays": { recapEn: "Fixed length, checked bounds: Java trades C's silent corruption for a loud exception.", recapBn: "Fixed length, checked bound: Java C-র নীরব corruption-এর বদলে জোরালো exception বেছে নেয়।" },
  "l4-jv-strings": { recapEn: "== compares objects, .equals compares contents — the trap that pools hide in tests and production exposes.", recapBn: "== object তুলনা করে, .equals content তুলনা করে — যেই ফাঁদ pool test-এ লুকায় আর production প্রকাশ করে।" },
  "l4-jv-methods": { recapEn: "Signatures are contracts: name + parameters; static belongs to the class; everything passes by value.", recapBn: "Signature হলো contract: নাম + parameter; static class-এর; সবকিছু pass by value হয়।" },
  "l4-jv-oop1": { recapEn: "Constructors are birth gates: this.name = name, and no object exists half-initialised.", recapBn: "Constructor হলো জন্মের gate: this.name = name, আর কোনো object অর্ধ-initialise অবস্থায় থাকে না।" },
  "l4-jv-oop2": { recapEn: "super() first, @Override always, and dispatch follows the object — never the variable's type.", recapBn: "আগে super(), সবসময় @Override, আর dispatch object অনুসরণ করে — কখনো variable-এর type নয়।" },
  "l4-jv-oop3": { recapEn: "Program to the interface; abstract classes add shared state; private + final make invariants unbreakable.", recapBn: "Interface-এর দিকে program করো; abstract class shared state যোগ করে; private + final invariant অভাঙনীয় করে।" },
  "l4-jv-exceptions": { recapEn: "Checked exceptions make failure handling part of the signature; finally always runs; catch specifically.", recapBn: "Checked exception failure handling-কে signature-এর অংশ করে; finally সবসময় চলে; নির্দিষ্টভাবে catch করো।" },
  "l4-jv-collections": { recapEn: "List keeps order and duplicates, Set enforces uniqueness, Map counts with merge — declare by interface.", recapBn: "List ক্রম আর duplicate রাখে, Set uniqueness প্রয়োগ করে, Map merge দিয়ে গোনে — interface দিয়ে declare করো।" },
  "l4-jv-generics": { recapEn: "Generics move type errors to compile time; erasure is the honest limit at runtime.", recapBn: "Generics type error compile time-এ সরায়; erasure হলো runtime-এ সৎ সীমা।" },
  "l4-jv-lambdas": { recapEn: "Streams are lazy recipes: filter selects, map transforms, and only a terminal operation cooks.", recapBn: "Stream হলো lazy recipe: filter select করে, map transform করে, আর শুধু terminal operation রাঁধে।" },
  "l4-jv-files": { recapEn: "Small files whole, real logs streamed, try-with-resources so close is guaranteed by construction.", recapBn: "ছোট file পুরো, আসল log streamed, try-with-resources যাতে close নির্মাণেই নিশ্চিত।" },
  "l4-jv-security": { recapEn: "Validate in layers, compare secrets in constant time, escape output, parameterise SQL.", recapBn: "স্তরে validate করো, constant time-এ secret তুলনা করো, output escape করো, SQL parameterise করো।" },
};

